  char   *message;
{
  char   *cmdStr, *fnStr, verbStr[MAXCMD + 1], argStr[MAXARG + 1];
  static long start, stop;
  int     argType, returnValue;
  unsigned int i;

  /* skip execution */
  if (skipCounter > 0) {
    --skipCounter;
    return STEP;
  }
  inCdb = TRUE;
  /* do some display related stuff */
#if defined(DOSALLGRAPHX)
  if (displayMode == TEXT) {
    switch_page(CDB_PAGE);
    /* show_cursor();  */
  } else
    write_menu();
#else
#if defined(DOSTXTGRAPHX)
  switch_page(CDB_PAGE);
  /* show_cursor(); */
#else
#if defined(DOSGRXGRAPHX)
  write_menu();
#else
#if defined(LINUXGRAPHX)
  svga_write_menu();
#else
#if defined(XWINGRAPHX)
  xWin_write_menu();
#endif
#endif
#endif
#endif
#endif

  W2 = W->nextWarrior;
  if (targetID == QUEUE) {
    curAddr = 0;
    QW = W;
    targetSize = (QW->tasks ? QW->tasks : 1);        /* at least 1, otherwise
                                                 * we'll get an exception in
                                                 * pqueue mode */
#ifdef QUEUEDEBUG
    for (i = 0; i < targetSize; i++)
      printf("%d ", queue(i));
    printf("\n");
#endif
  } else if (targetID == WARRIOR) {
    curAddr = W - warrior;
    /* targetSize = warriors; */
  } else if (targetID == PSP) {
    QW = W;
  } else {
    curAddr = progCnt;
    targetSize = coreSize;
  }

